class Solution {
    public int maxDistance(List<List<Integer>> arrays){
        int minimum=arrays.get(0).get(0),maximum=arrays.get(0).get(arrays.get(0).size()-1),best=0;
        for(int i=1;i<arrays.size();i++){
            List<Integer> array=arrays.get(i);
            int first=array.get(0),last=array.get(array.size()-1);
            best=Math.max(best,Math.max(Math.abs(last-minimum),Math.abs(maximum-first)));
            minimum=Math.min(minimum,first);
            maximum=Math.max(maximum,last);
        }
        return best;
    }
}

code.kotlin:
class Solution {
    fun maxDistance(arrays:List<List<Int>>):Int{
        var minimum=arrays[0][0];
        var maximum=arrays[0].last();
        var best=0;
        for(i in 1 until arrays.size){
            val first=arrays[i][0];
            val last=arrays[i].last();
            best=maxOf(best,kotlin.math.abs(last-minimum),kotlin.math.abs(maximum-first));
            minimum=minOf(minimum,first);
            maximum=maxOf(maximum,last)
        };
        return best
    }
}

